import {
    Table,
    BasicImageColumn,
    BooleanColumn,
    ConditionsColumn,
    DecimalColumn,
    DomainIdColumn,
    DomainPathColumn,
    GuidColumn,
    ReferenceColumn,
    StringColumn,
    TableNameColumn,
    TranslatedFieldColumn,
    UserRolesColumn,
} from '../../db'

export const sys_app_module = Table({
    actions: {
        read: true,
        update: true,
        delete: true,
        create: true,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_list_protection: true,
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    display: 'title',
    extends: 'sys_metadata',
    label: [
        {
            label: 'Module',
            help: 'Links available to display within application menus',
        },
    ],
    name: 'sys_app_module',
    schema: {
        route: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Route',
            maxLength: 32,
            referenceTable: 'sys_ux_app_route',
        }),
        roles: UserRolesColumn({
            array: true,
            attributes: {
                no_truncate: true,
            },
            label: 'Roles',
            maxLength: 100,
        }),
        mobile_view_name: StringColumn({
            default: 'Mobile',
            label: [
                {
                    hint: 'View used for mobile devices',
                    label: 'Mobile view name',
                    plural: 'Mobile view names',
                },
            ],
            maxLength: 40,
        }),
        application: ReferenceColumn({
            label: [
                {
                    hint: 'The navigation menu where this module should reside',
                    label: 'Application menu',
                    plural: 'Application menu',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_app_application',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
            maxLength: 32,
        }),
        report: ReferenceColumn({
            dependent: 'name,table',
            label: 'Report',
            maxLength: 32,
            referenceTable: 'sys_report',
        }),
        screen: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Screen',
            maxLength: 32,
            referenceTable: 'sys_ux_screen',
        }),
        image: BasicImageColumn({
            label: 'Image (UI11)',
            maxLength: 100,
        }),
        timeline_page: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Timeline page',
            maxLength: 32,
            referenceTable: 'cmn_timeline_page',
        }),
        filter: ConditionsColumn({
            dependent: 'name',
            label: 'Filter',
            maxLength: 3500,
        }),
        mobile_title: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Display name on mobile devices',
                    label: 'Mobile title',
                    plural: 'Mobile titles',
                },
            ],
            maxLength: 80,
        }),
        title: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Display name of the module',
                    label: 'Title',
                    plural: 'Titles',
                },
            ],
            maxLength: 80,
        }),
        link_type: StringColumn({
            default: 'LIST',
            choices: {
                ASSESSMENT: {
                    label: 'Assessment',
                },
                CONTENT_PAGE: {
                    label: 'Content Page',
                },
                DETAIL: {
                    label: 'Single Record',
                },
                DIRECT: {
                    label: 'URL (from Arguments:)',
                },
                DOC_LINK: {
                    label: 'Documentation Link',
                },
                FILTER: {
                    label: 'List Filter',
                },
                HOMEPAGE: {
                    label: 'Homepage',
                    inactive: true,
                },
                HTML: {
                    label: 'HTML (from Arguments:)',
                },
                LIST: {
                    label: 'List of Records',
                },
                MAP: {
                    label: 'Map Page',
                },
                NEW: {
                    label: 'New Record',
                },
                REPORT: {
                    label: 'Run a Report',
                },
                SCRIPT: {
                    label: 'Script (from Arguments:)',
                },
                SEARCH: {
                    label: 'Search Screen',
                },
                SEPARATOR: {
                    label: 'Separator',
                },
                SURVEY: {
                    label: 'Survey',
                },
                TIMELINE: {
                    label: 'Timeline Page',
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Link type',
            maxLength: 40,
        }),
        require_confirmation: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'When selected, Script (from Arguments:) will require the user to click a button to confirm execution.',
                    label: 'Require confirmation',
                    plural: 'Require confirmations',
                },
            ],
            maxLength: 40,
        }),
        order: DecimalColumn({
            label: 'Order',
            maxLength: 15,
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
            maxLength: 255,
        }),
        query: StringColumn({
            label: 'Arguments',
            maxLength: 3500,
        }),
        device_type: StringColumn({
            choices: {
                any: {
                    label: 'Any',
                },
                browser: {
                    label: 'Browser',
                },
                mobile: {
                    label: 'Mobile',
                },
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Devices on which this module is available.  Uses the application menu setting if not specified.',
                    label: 'Device type',
                    plural: 'Device types',
                },
            ],
            maxLength: 40,
        }),
        homepage: ReferenceColumn({
            label: 'Homepage',
            maxLength: 32,
            referenceTable: 'sys_portal_page',
            referenceQual: 'view!=',
            useReferenceQualifier: 'simple',
        }),
        uncancelable: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If this module is clicked, then another module is clicked, Setting this to true will prevent this module from being canceled.',
                    label: 'Uncancelable by Other Modules',
                    plural: 'Uncancelable by Other Modules',
                },
            ],
            maxLength: 40,
        }),
        window_name: StringColumn({
            label: 'Window name',
            maxLength: 40,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
            maxLength: 40,
        }),
        sys_overrides: ReferenceColumn({
            label: [
                {
                    hint: 'Module being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_app_module',
        }),
        map_page: ReferenceColumn({
            label: 'Map page',
            maxLength: 32,
            referenceTable: 'cmn_map_page',
        }),
        hint: TranslatedFieldColumn({
            attributes: {
                no_truncate: true,
            },
            label: 'Hint',
            maxLength: 255,
        }),
        // Was GenericColumn({ column_type: 'GUID', read_only: false, active: true }) — the generic
        // escape hatch plus the deprecated snake_case props, standing in for the primary key.
        // GuidColumn is the dedicated type for it and expresses `primary` directly. Both produce a
        // string value type, so nothing a developer can write changes.
        sys_id: GuidColumn({
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        ux_list: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'UX List',
            maxLength: 32,
            referenceTable: 'sys_ux_list',
        }),
        name: TableNameColumn({
            attributes: {
                allow_public: true,
            },
            label: 'Table',
            maxLength: 80,
            tableReference: true,
        }),
        view_name: StringColumn({
            default:
                "javascript:var viewDefault='';if(current.device_type=='mobile') viewDefault='Mobile';else if(!current.application.nil() && current.application.device_type=='mobile' && current.device_type.nil()) viewDefault='Mobile';viewDefault",
            label: 'View name',
            maxLength: 40,
        }),
        override_menu_roles: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show this module when the user has the specified roles.  Otherwise the user must have the roles specified by both the application menu and the module.',
                    label: 'Override application menu roles',
                    plural: 'Override application menu roles',
                },
            ],
            maxLength: 40,
        }),
        assessment: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Assessment',
            maxLength: 32,
            referenceTable: 'asmt_metric_type',
        }),
    },
    textIndex: true,
})
